cyber_enterprise_suite.styles:

:root {
    --bg-deep: #03050b;
    --bg-surface: rgba(10, 15, 30, 0.90);
    --bg-surface-glass: rgba(16, 24, 48, 0.65);
    --neon-cyan: #00f0ff;
    --neon-pink: #ff007f;
    --neon-purple: #9d00ff;
    --neon-green: #00ff66;
    --neon-yellow: #ffee00;
    --text-main: #f0f6fc;
    --text-muted: #8b949e;
    --border-glow: rgba(0, 240, 255, 0.3);
    --card-border: rgba(255, 255, 255, 0.08);
    --font-mono: 'JetBrains Mono', 'Fira Code', Consolas, monospace;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

body {
    background-color: var(--bg-deep);
    color: var(--text-main);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 24px 16px;
    overflow-x: hidden;
    position: relative;
}

body::before {
    content: '';
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 1000px;
    height: 500px;
    background: radial-gradient(circle, rgba(0,240,255,0.1) 0%, rgba(157,0,255,0.05) 50%, transparent 100%);
    z-index: -1;
    filter: blur(100px);
}

.suite-wrapper {
    width: 100%;
    max-width: 1350px;
    display: flex;
    flex-direction: column;
    gap: 24px;
    z-index: 2;
}

/* Top Navigation Header */
.suite-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--bg-surface);
    padding: 18px 28px;
    border-radius: 16px;
    border: 1px solid var(--border-glow);
    box-shadow: 0 0 30px rgba(0, 240, 255, 0.15);
    backdrop-filter: blur(16px);
}

.brand-cluster {
    display: flex;
    align-items: center;
    gap: 16px;
}

.brand-icon {
    width: 44px;
    height: 44px;
    object-fit: contain;
    filter: drop-shadow(0 0 10px var(--neon-cyan));
    animation: icon-pulse 3s infinite ease-in-out;
}

@keyframes icon-pulse {
    0%, 100% { filter: drop-shadow(0 0 8px var(--neon-cyan)); transform: scale(1); }
    50% { filter: drop-shadow(0 0 20px var(--neon-cyan)); transform: scale(1.05); }
}

.brand-info h1 {
    font-size: 1.3rem;
    font-weight: 800;
    letter-spacing: 1.5px;
    background: linear-gradient(90deg, #fff, var(--neon-cyan));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.brand-info span {
    font-size: 0.75rem;
    color: var(--text-muted);
    letter-spacing: 1px;
    text-transform: uppercase;
}

/* Mode Switcher Tabs */
.mode-switcher {
    display: flex;
    gap: 10px;
    background: rgba(0, 0, 0, 0.4);
    padding: 6px;
    border-radius: 12px;
    border: 1px solid var(--card-border);
}

.mode-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    padding: 8px 18px;
    font-size: 0.85rem;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

.mode-btn:hover {
    color: var(--text-main);
    background: rgba(255, 255, 255, 0.05);
}

.mode-btn.active {
    background: linear-gradient(135deg, rgba(0, 240, 255, 0.2), rgba(157, 0, 255, 0.2));
    color: var(--neon-cyan);
    border: 1px solid rgba(0, 240, 255, 0.4);
    box-shadow: 0 0 15px rgba(0, 240, 255, 0.2);
}

.system-indicators {
    display: flex;
    align-items: center;
    gap: 16px;
}

.status-badge {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.8rem;
    color: var(--neon-green);
    background: rgba(0, 255, 102, 0.08);
    padding: 6px 14px;
    border-radius: 20px;
    border: 1px solid rgba(0, 255, 102, 0.25);
}

.status-dot {
    width: 7px;
    height: 7px;
    background-color: var(--neon-green);
    border-radius: 50%;
    box-shadow: 0 0 8px var(--neon-green);
    animation: pulse-dot 1.5s infinite;
}

@keyframes pulse-dot {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
}

/* Workspace Views */
.workspace-view {
    display: none;
    width: 100%;
    animation: fadeIn 0.3s ease forwards;
}

.workspace-view.active {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
}

/* 1. PLANNING MODE STYLES */
.planning-grid {
    display: grid;
    grid-template-columns: 350px 1fr;
    gap: 20px;
}

.panel-card {
    background: var(--bg-surface);
    border: 1px solid var(--card-border);
    border-radius: 14px;
    padding: 20px;
    backdrop-filter: blur(12px);
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.panel-title {
    font-size: 1rem;
    font-weight: 700;
    color: var(--neon-cyan);
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid var(--card-border);
    padding-bottom: 10px;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.form-group label {
    font-size: 0.8rem;
    color: var(--text-muted);
    font-weight: 600;
    text-transform: uppercase;
}

.form-group input, .form-group textarea, .form-group select {
    background: rgba(0, 0, 0, 0.4);
    border: 1px solid var(--card-border);
    border-radius: 8px;
    padding: 10px 12px;
    color: var(--text-main);
    font-size: 0.9rem;
    outline: none;
    transition: all 0.2s ease;
}

.form-group input:focus, .form-group textarea:focus, .form-group select:focus {
    border-color: var(--neon-cyan);
    box-shadow: 0 0 10px rgba(0, 240, 255, 0.2);
}

.action-btn {
    background: linear-gradient(135deg, rgba(0, 240, 255, 0.15), rgba(157, 0, 255, 0.15));
    border: 1px solid rgba(0, 240, 255, 0.3);
    color: var(--neon-cyan);
    padding: 10px 16px;
    font-size: 0.85rem;
    font-weight: 700;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    text-align: center;
}

.action-btn:hover {
    background: var(--neon-cyan);
    color: #000;
    box-shadow: 0 0 20px var(--neon-cyan);
}

.milestone-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    max-height: 480px;
    overflow-y: auto;
    padding-right: 4px;
}

.milestone-item {
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    padding: 14px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    position: relative;
    transition: all 0.2s ease;
}

.milestone-item:hover {
    border-color: rgba(0, 240, 255, 0.4);
    background: rgba(0, 240, 255, 0.02);
}

.milestone-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.milestone-title {
    font-size: 0.95rem;
    font-weight: 700;
    color: #fff;
}

.milestone-tag {
    font-size: 0.7rem;
    padding: 3px 8px;
    border-radius: 12px;
    background: rgba(157, 0, 255, 0.15);
    color: var(--neon-purple);
    border: 1px solid rgba(157, 0, 255, 0.3);
}

.milestone-desc {
    font-size: 0.85rem;
    color: var(--text-muted);
}

/* 2. ENCHANT MODE STYLES */
.enchant-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

.enchant-canvas-box {
    position: relative;
    background: #000;
    border: 1px solid var(--border-glow);
    border-radius: 14px;
    height: 450px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    box-shadow: inset 0 0 30px rgba(0, 240, 255, 0.1);
}

#enchantCanvas {
    width: 100%;
    height: 100%;
}

.enchant-controls {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.slider-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.slider-header {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: var(--text-muted);
}

input[type="range"] {
    -webkit-appearance: none;
    width: 100%;
    height: 6px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 3px;
    outline: none;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--neon-cyan);
    cursor: pointer;
    box-shadow: 0 0 10px var(--neon-cyan);
}

/* 3. AGENT EXECUTION MODE STYLES */
.agent-container {
    display: grid;
    grid-template-columns: 1fr 380px;
    gap: 20px;
}

.code-executor-box {
    background: var(--bg-surface);
    border: 1px solid var(--card-border);
    border-radius: 14px;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    height: 520px;
}

.editor-header {
    background: rgba(0, 0, 0, 0.5);
    padding: 12px 18px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--card-border);
}

.editor-tabs {
    display: flex;
    gap: 8px;
}

.editor-tab {
    font-size: 0.8rem;
    color: var(--text-muted);
    background: rgba(255, 255, 255, 0.03);
    padding: 6px 14px;
    border-radius: 6px;
    cursor: pointer;
    border: 1px solid var(--card-border);
}

.editor-tab.active {
    color: var(--neon-cyan);
    background: rgba(0, 240, 255, 0.1);
    border-color: rgba(0, 240, 255, 0.3);
}

.code-textarea {
    flex-grow: 1;
    background: rgba(2, 4, 8, 0.95);
    color: #7ee787;
    font-family: var(--font-mono);
    font-size: 0.85rem;
    padding: 16px;
    border: none;
    resize: none;
    outline: none;
    line-height: 1.5;
}

.console-output {
    background: #000;
    border-top: 1px solid var(--card-border);
    padding: 12px 16px;
    font-family: var(--font-mono);
    font-size: 0.8rem;
    color: var(--neon-yellow);
    max-height: 120px;
    overflow-y: auto;
}

.agent-sidebar {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.agent-log-box {
    background: rgba(0, 0, 0, 0.5);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    padding: 12px;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--text-muted);
    height: 340px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.log-entry {
    border-left: 2px solid var(--neon-cyan);
    padding-left: 8px;
}

.log-entry.success { border-left-color: var(--neon-green); color: #a5d6ff; }
.log-entry.error { border-left-color: var(--neon-pink); color: #ff7b72; }

/* Local Storage Status Indicator Bar */
.sync-bar {
    background: var(--bg-surface);
    border: 1px solid var(--card-border);
    border-radius: 10px;
    padding: 10px 18px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.8rem;
    color: var(--text-muted);
}

.sync-status-text {
    color: var(--neon-cyan);
    font-weight: 600;
}

/* Click Bubble FX */
.click-burst {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    transform: translate(-50%, -50%);
    animation: burst-anim 0.6s cubic-bezier(0.25, 1, 0.5, 1) forwards;
    z-index: 9999;
}

@keyframes burst-anim {
    0% { width: 10px; height: 10px; opacity: 1; box-shadow: 0 0 10px var(--neon-cyan); border: 2px solid var(--neon-cyan); }
    100% { width: 80px; height: 80px; opacity: 0; transform: translate(-50%, -50%) scale(1.3); box-shadow: 0 0 25px var(--neon-pink); border: 1px solid var(--neon-pink); }
}

div.textarea:
// CyberCore Sandbox Execution Engine
// Write or load JavaScript to execute inside local VM sandbox.
function runSimulation() {
    const metrics = { nodes: 128, throughput: "4.8 GB/s", status: "OPTIMIZED" };
    console.log("Simulation initialized successfully.");
    return metrics;
}
return runSimulation();

cyber_enterprise_suite.script:

// ==========================================
// LOCAL STORAGE & STATE MANAGEMENT
// ==========================================
const STORAGE_KEY = "cybercore_enterprise_suite_db_v1";

function loadAppData() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) {
            return {
                milestones: [
                    { id: "1", title: "Initialize Core Architecture", category: "Architecture", desc: "Establish local storage synchronization and base UI framework." },
                    { id: "2", title: "Quantum Particle Shaders", category: "Rendering", desc: "Tune canvas particle emission and neon glow frequency." }
                ]
            };
        }
        return JSON.parse(raw);
    } catch (e) {
        console.error("Failed to load local storage data", e);
        return { milestones: [] };
    }
}

function saveAppData(data) {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
        updateSyncIndicator();
    } catch (e) {
        console.error("Failed to save local storage data", e);
    }
}

function updateSyncIndicator() {
    const data = loadAppData();
    const count = data.milestones.length;
    const indicator = document.getElementById("syncIndicator");
    if (indicator) {
        indicator.textContent = `Synchronized (${count} items stored locally)`;
    }
    renderMilestones();
}

function clearLocalStorageData() {
    localStorage.removeItem(STORAGE_KEY);
    updateSyncIndicator();
    appendAgentLog("Local storage vault cleared.", "error");
}

// ==========================================
// MODE SWITCHING LOGIC
// ==========================================
function switchMode(mode, btn) {
    document.querySelectorAll('.workspace-view').forEach(v => v.classList.remove('active'));
    document.querySelectorAll('.mode-btn').forEach(b => b.classList.remove('active'));

    const targetView = document.getElementById(`view-${mode}`);
    if (targetView) targetView.classList.add('active');
    if (btn) btn.classList.add('active');

    if (mode === 'enchant') {
        initEnchantCanvas();
    }
}

// ==========================================
// PLANNING MODE FUNCTIONS
// ==========================================
function addPlanningMilestone() {
    const titleInput = document.getElementById("planTitleInput");
    const catInput = document.getElementById("planCategoryInput");
    const descInput = document.getElementById("planDescInput");

    if (!titleInput.value.trim()) {
        alert("Please enter a milestone title.");
        return;
    }

    const data = loadAppData();
    const newMilestone = {
        id: Date.now().toString(),
        title: titleInput.value.trim(),
        category: catInput.value,
        desc: descInput.value.trim() || "No tactical description provided."
    };

    data.milestones.unshift(newMilestone);
    saveAppData(data);

    titleInput.value = "";
    descInput.value = "";
    appendAgentLog(`Milestone committed: "${newMilestone.title}"`, "success");
}

function deleteMilestone(id) {
    const data = loadAppData();
    data.milestones = data.milestones.filter(m => m.id !== id);
    saveAppData(data);
    appendAgentLog(`Milestone ID ${id} removed from local vault.`, "error");
}

function renderMilestones() {
    const container = document.getElementById("milestoneListContainer");
    const countLabel = document.getElementById("milestoneCount");
    if (!container) return;

    const data = loadAppData();
    countLabel.textContent = `${data.milestones.length} Items`;

    if (data.milestones.length === 0) {
        container.innerHTML = `<div style="text-align: center; color: var(--text-muted); padding: 30px;">No milestones in local registry. Add one using the form.</div>`;
        return;
    }

    container.innerHTML = "";
    data.milestones.forEach(m => {
        const item = document.createElement("div");
        item.className = "milestone-item";
        item.innerHTML = `
            <div class="milestone-header">
                <span class="milestone-title">${escapeHtml(m.title)}</span>
                <span class="milestone-tag">${escapeHtml(m.category)}</span>
            </div>
            <div class="milestone-desc">${escapeHtml(m.desc)}</div>
            <button class="action-btn" style="padding: 4px 10px; font-size: 0.75rem; align-self: flex-start; margin-top: 6px;" onclick="deleteMilestone('${m.id}')">Delete</button>
        `;
        container.appendChild(item);
    });
}

// ==========================================
// ENCHANT MODE CANVAS SIMULATOR
// ==========================================
let enchantParams = { emission: 50, radius: 80, freq: 1.5 };
let enchantAnimId = null;

function updateEnchantParam(param, val) {
    enchantParams[param] = parseFloat(val);
    document.getElementById(`val${param.charAt(0).toUpperCase() + param.slice(1)}`).textContent = val;
}

function initEnchantCanvas() {
    const canvas = document.getElementById("enchantCanvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    canvas.width = canvas.parentElement.clientWidth;
    canvas.height = canvas.parentElement.clientHeight;

    let particles = [];
    for (let i = 0; i < 150; i++) {
        particles.push({
            x: Math.random() * canvas.width,
            y: Math.random() * canvas.height,
            vx: (Math.random() - 0.5) * 2,
            vy: (Math.random() - 0.5) * 2,
            size: Math.random() * 3 + 1,
            color: Math.random() > 0.5 ? '#00f0ff' : '#ff007f'
        });
    }

    if (enchantAnimId) cancelAnimationFrame(enchantAnimId);

    function renderLoop() {
        ctx.fillStyle = 'rgba(3, 5, 11, 0.25)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        const limit = enchantParams.emission * 2;
        while (particles.length < limit) {
            particles.push({
                x: canvas.width / 2,
                y: canvas.height / 2,
                vx: (Math.random() - 0.5) * 4,
                vy: (Math.random() - 0.5) * 4,
                size: Math.random() * 3 + 1,
                color: '#9d00ff'
            });
        }
        if (particles.length > limit) particles = particles.slice(0, limit);

        particles.forEach(p => {
            p.x += p.vx * enchantParams.freq;
            p.y += p.vy * enchantParams.freq;

            if (p.x < 0 || p.x > canvas.width) p.vx *= -1;
            if (p.y < 0 || p.y > canvas.height) p.vy *= -1;

            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fillStyle = p.color;
            ctx.shadowBlur = enchantParams.radius / 5;
            ctx.shadowColor = p.color;
            ctx.fill();
        });

        enchantAnimId = requestAnimationFrame(renderLoop);
    }
    renderLoop();
}

function triggerEnchantPulse() {
    enchantParams.freq = 4.5;
    document.getElementById('sliderFreq').value = 4.5;
    document.getElementById('valFreq').textContent = "4.5";
    appendAgentLog("Enchant resonance burst triggered!", "success");
    setTimeout(() => {
        enchantParams.freq = 1.5;
        document.getElementById('sliderFreq').value = 1.5;
        document.getElementById('valFreq').textContent = "1.5";
    }, 1200);
}

// ==========================================
// AGENT EXECUTION & SANDBOX MODE
// ==========================================
function loadSampleScript(type) {
    const editor = document.getElementById("codeEditor");
    if (type === 'math') {
        editor.value = "// Matrix Vector Multiplication Benchmark\nfunction benchmark() {\n    let matrix = [[1, 2], [3, 4]];\n    let vector = [10, 20];\n    let result = [matrix[0][0]*vector[0] + matrix[0][1]*vector[1], matrix[1][0]*vector[0] + matrix[1][1]*vector[1]];\n    console.log('Matrix calculation complete:', result);\n    return result;\n}\nreturn benchmark();";
    } else if (type === 'async') {
        editor.value = "// Simulated Async Agent Network Protocol\nasync function pollNetwork() {\n    console.log('Dispatching ping to local node...');\n    return new Promise(resolve => {\n        setTimeout(() => {\n            resolve({ status: 'CONNECTED', latencyMs: 14 });\n        }, 500);\n    });\n}\nreturn pollNetwork();";
    }
    document.querySelectorAll('.editor-tab').forEach(t => t.classList.remove('active'));
    event.target.classList.add('active');
}

function executeSandboxCode() {
    const code = document.getElementById("codeEditor").value;
    const consoleBox = document.getElementById("consoleOutput");
    consoleBox.innerHTML = "> Executing sandbox script...\n";

    // Intercept console.log
    let logs = [];
    const originalLog = console.log;
    console.log = function(...args) {
        logs.push(args.map(a => typeof a === 'object' ? JSON.stringify(a) : a).join(' '));
        originalLog.apply(console, args);
    };

    try {
        const func = new Function(code);
        const res = func();
        console.log = originalLog;

        let outputText = logs.join("\n");
        if (res !== undefined) {
            outputText += `\n[Return Value]: ${JSON.stringify(res, null, 2)}`;
        }
        consoleBox.innerHTML = `> Execution Successful.\n${outputText}`;
        appendAgentLog("Sandbox script executed successfully.", "success");
    } catch (err) {
        console.log = originalLog;
        consoleBox.innerHTML = `> Execution Error: ${err.message}`;
        appendAgentLog(`Sandbox error: ${err.message}`, "error");
    }
}

function dispatchAutonomousAgent() {
    appendAgentLog("Dispatching sub-agent for local vault reconciliation...", "success");
    setTimeout(() => {
        const data = loadAppData();
        appendAgentLog(`Sub-agent check complete. Verified ${data.milestones.length} active milestones.`, "success");
    }, 800);
}

function appendAgentLog(msg, type = "") {
    const logBox = document.getElementById("agentLogBox");
    if (!logBox) return;
    const entry = document.createElement("div");
    entry.className = `log-entry ${type}`;
    const timeStr = new Date().toLocaleTimeString();
    entry.textContent = `[${timeStr}] ${msg}`;
    logBox.appendChild(entry);
    logBox.scrollTop = logBox.scrollHeight;
}

// ==========================================
// UTILITIES & GLOBAL LISTENERS
// ==========================================
function escapeHtml(str) {
    return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

// Global Click Bubble Burst Effect
document.addEventListener('click', function(e) {
    const burst = document.createElement('div');
    burst.className = 'click-burst';
    burst.style.left = e.pageX + 'px';
    burst.style.top = e.pageY + 'px';
    document.body.appendChild(burst);
    setTimeout(() => burst.remove(), 600);
});

